from collections import defaultdict
from typing import List

class Solution:
    def maxAlternatingSum(self, nums: List[int], pairs: List[List[int]]) -> int:
        n = len(nums)
        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            root_x, root_y = find(x), find(y)
            if root_x != root_y:
                parent[root_x] = root_y

        for u, v in pairs:
            union(u, v)

        components = defaultdict(list)
        for i in range(n):
            components[find(i)].append(i)

        # Reconstruct optimal placement in each component
        # Alternating sum: sum(nums[i] * (-1)^i)
        # Even indices are positive (+), odd indices are negative (-)
        res = list(nums)
        for comp, indices in components.items():
            vals = sorted([nums[i] for i in indices], reverse=True)
            # Count even indices and odd indices in this component
            even_indices = [i for i in indices if i % 2 == 0]
            odd_indices = [i for i in indices if i % 2 == 1]

            # Place largest values at even indices, smallest values at odd indices
            for i, idx in enumerate(even_indices):
                res[idx] = vals[i]
            for i, idx in enumerate(odd_indices):
                res[idx] = vals[len(even_indices) + len(odd_indices) - 1 - i]

        return sum(res[i] if i % 2 == 0 else -res[i] for i in range(n))
