#include <vector>
#include <unordered_map>
#include <algorithm>
#include <numeric>

class Solution {
    struct DSU {
        std::vector<int> parent;
        DSU(int n) : parent(n) {
            std::iota(parent.begin(), parent.end(), 0);
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        void unite(int x, int y) {
            int rx = find(x), ry = find(y);
            if (rx != ry) parent[rx] = ry;
        }
    };

public:
    long long maxAlternatingSum(std::vector<int>& nums, std::vector<std::vector<int>>& pairs) {
        int n = nums.size();
        DSU dsu(n);
        for (const auto& p : pairs) {
            dsu.unite(p[0], p[1]);
        }

        std::unordered_map<int, std::vector<int>> comp;
        for (int i = 0; i < n; ++i) {
            comp[dsu.find(i)].push_back(i);
        }

        std::vector<int> res = nums;
        for (auto& [root, indices] : comp) {
            std::vector<int> vals;
            std::vector<int> evens, odds;
            for (int idx : indices) {
                vals.push_back(nums[idx]);
                if (idx % 2 == 0) evens.push_back(idx);
                else odds.push_back(idx);
            }
            std::sort(vals.begin(), vals.end(), std::greater<int>());

            for (size_t i = 0; i < evens.size(); ++i) {
                res[evens[i]] = vals[i];
            }
            for (size_t i = 0; i < odds.size(); ++i) {
                res[odds[i]] = vals[evens.size() + odds.size() - 1 - i];
            }
        }

        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            ans += (i % 2 == 0 ? res[i] : -res[i]);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long maxAlternatingSum(int[] nums, int[][] pairs) {
        int n = nums.length;
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        for (int[] p : pairs) {
            union(parent, p[0], p[1]);
        }

        Map<Integer, List<Integer>> comp = new HashMap<>();
        for (int i = 0; i < n; i++) {
            comp.computeIfAbsent(find(parent, i), k -> new ArrayList<>()).add(i);
        }

        int[] res = nums.clone();
        for (List<Integer> indices : comp.values()) {
            List<Integer> vals = new ArrayList<>();
            List<Integer> evens = new ArrayList<>();
            List<Integer> odds = new ArrayList<>();

            for (int idx : indices) {
                vals.add(nums[idx]);
                if (idx % 2 == 0) evens.add(idx);
                else odds.add(idx);
            }
            vals.sort(Collections.reverseOrder());

            for (int i = 0; i < evens.size(); i++) {
                res[evens.get(i)] = vals.get(i);
            }
            for (int i = 0; i < odds.size(); i++) {
                res[odds.get(i)] = vals.get(evens.size() + odds.size() - 1 - i);
            }
        }

        long ans = 0;
        for (int i = 0; i < n; i++) {
            ans += (i % 2 == 0 ? res[i] : -res[i]);
        }
        return ans;
    }

    private int find(int[] parent, int x) {
        if (parent[x] != x) parent[x] = find(parent, parent[x]);
        return parent[x];
    }

    private void union(int[] parent, int x, int y) {
        int rx = find(parent, x), ry = find(parent, y);
        if (rx != ry) parent[rx] = ry;
    }
}

var maxAlternatingSum = function(nums, pairs) {
    const n = nums.length;
    const parent = Array.from({ length: n }, (_, i) => i);

    function find(x) {
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    }

    function union(x, y) {
        const rx = find(x), ry = find(y);
        if (rx !== ry) parent[rx] = ry;
    }

    for (const [u, v] of pairs) union(u, v);

    const comp = new Map();
    for (let i = 0; i < n; i++) {
        const root = find(i);
        if (!comp.has(root)) comp.set(root, []);
        comp.get(root).push(i);
    }

    const res = nums.slice();
    for (const indices of comp.values()) {
        const vals = indices.map(i => nums[i]).sort((a, b) => b - a);
        const evens = indices.filter(i => i % 2 === 0);
        const odds = indices.filter(i => i % 2 === 1);

        for (let i = 0; i < evens.length; i++) {
            res[evens[i]] = vals[i];
        }
        for (let i = 0; i < odds.length; i++) {
            res[odds[i]] = vals[evens.length + odds.length - 1 - i];
        }
    }

    let ans = 0;
    for (let i = 0; i < n; i++) {
        ans += (i % 2 === 0 ? res[i] : -res[i]);
    }
    return ans;
};
